<span class="line"><span style="color:#E06C75;">                    libexecdir</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&quot;</span><span style="color:#E06C75;">$basedir</span><span style="color:#98C379;">/libexec&quot;</span></span>
