<span class="line"><span style="color:#C678DD;">    if</span><span style="color:#56B6C2;"> test</span><span style="color:#D19A66;"> -x</span><span style="color:#E06C75;"> $manager</span><span style="color:#D19A66;"> -a</span><span style="color:#98C379;"> &quot;</span><span style="color:#E06C75;">$use_mysqld_safe</span><span style="color:#98C379;">&quot;</span><span style="color:#98C379;"> =</span><span style="color:#98C379;"> &quot;0&quot;</span></span>
