<span class="line"><span style="color:#D19A66;">        --pid-file=</span><span style="color:#98C379;">&quot;</span><span style="color:#E06C75;">$pid_file</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;"> &gt;</span><span style="color:#98C379;">/dev/null</span><span style="color:#ABB2BF;"> 2&gt;&amp;1 &amp;</span></span>
