<span class="line"><span style="color:#C678DD;">      if</span><span style="color:#ABB2BF;"> (</span><span style="color:#56B6C2;">kill</span><span style="color:#D19A66;"> -0</span><span style="color:#E06C75;"> $mysqlmanager_pid</span><span style="color:#ABB2BF;"> 2&gt;</span><span style="color:#98C379;">/dev/null</span><span style="color:#ABB2BF;">)</span></span>
